		{x=754,y=530,w=561,avail=43,size=40,fg={90,60,33},bg={223,215,193},cover={{754,530,1315,569}},ko="속성 상세: 획득 비용과 횟수"},
		{x=801,y=570,w=514,avail=38,size=14,fg={90,60,33},bg={255,253,236},cover={{811,570,1315,585},{801,589,906,601}},ko="처음에는 1 포인트가 들지만, 같은 능력치를 많이 올릴수록 비용이 비싸집니다."},
		{x=800,y=620,w=518,avail=95,size=17,fg={90,60,33},bg={255,253,236},cover={{800,620,892,632},{810,639,1318,655},{800,658,1302,676},{800,678,1053,695},{811,699,1146,714}},ko="초기화 버튼: 누르면 사용한 능력치 포인트를 모두 초기화하고 일부(85%)를 돌려줍니다. 최대 체력 패널티도 생기며, 둘 다 모드 설정에서 조절할 수 있습니다. 레벨과 경험치는 초기화되지 않습니다."},
		{x=801,y=729,w=509,avail=80,size=16,fg={90,60,33},bg={255,253,236},cover={{801,729,917,741},{810,747,1310,764},{801,767,865,782},{811,788,1183,803}},ko="펫 레벨 버튼: 누르면 펫 레벨 창으로 전환합니다. (자세한 내용은 능력(Abilities) 부분 참고) \"펫 미포함\" 특전을 보유한 경우에만 표시됩니다."},
	},
	["basic_guide_4"] = {
		{x=95,y=60,w=64,avail=41,size=38,fg={49,60,115},bg={255,253,236},cover={{95,60,159,97}},ko="팁 :"},
		{x=148,y=117,w=513,avail=38,size=17,fg={90,60,33},bg={255,253,236},cover={{148,117,655,133},{148,136,661,152}},ko="레벨업할 때마다 경험치가 초기화되고 다음 목표치도 올라갑니다. 즉 레벨이 높을수록 레벨업이 더 어려워집니다."},
		{x=80,y=186,w=591,avail=43,size=40,fg={90,60,33},bg={255,253,236},cover={{80,186,671,225}},ko="경험치는 작업, 몹 처치, 농사,"},
		{x=148,y=229,w=560,avail=125,size=17,fg={90,60,33},bg={255,253,236},cover={{148,229,703,245},{148,256,706,272},{148,276,708,292},{148,295,650,312},{148,314,706,341},{148,334,394,350}},ko="요리, 식사, 낚시, 제작, 채집으로 얻습니다. 일부 캐릭터는 자신이 특히 잘하는 작업을 할 때 다른 캐릭터보다 더 많은 경험치를 얻습니다. 우디와 맥스웰은 작업, 위그프리드는 몹 처치, 웜우드는 작물 심기, 왈리는 요리와 식사, 워트는 낚시, 위노나는 제작입니다. 보너스가 크니 잘 활용해야 합니다."},
		{x=87,y=375,w=617,avail=52,size=28,fg={90,60,33},bg={255,253,236},cover={{89,375,590,397},{87,391,704,423}},ko="웨스는 쓸모없음을 보완하기 위해 무엇을 하든 경험치를 25% 더 얻습니다."},
		{x=136,y=445,w=538,avail=80,size=17,fg={90,60,33},bg={255,253,236},cover={{136,445,666,461},{148,465,674,482},{136,486,636,502},{148,505,254,521}},ko="몹을 처치할 때 단독 처치는 경험치를 더 많이 줍니다. 그렇지 않으면 경험치가 피해를 주지 않은 근처 플레이어에게도 균등하게 나뉘기 때문입니다. 이를 어시스트 경험치라고 하며, 어시스트 범위는 모드 설정에서 조절할 수 있습니다."},
		{x=148,y=541,w=521,avail=80,size=18,fg={90,60,33},bg={255,253,236},cover={{148,541,669,558},{148,561,649,578},{148,581,654,598},{148,601,324,616}},ko="더 강한 몹을 잡고 더 좋은 음식을 먹으면 경험치를 더 많이 얻습니다. 건축물 제작이 아이템 제작보다, 바다 물고기 낚시가 연못 물고기보다, 특정 씨앗이 일반 씨앗보다 더 많이 줍니다."},
		{x=148,y=637,w=513,avail=76,size=18,fg={90,60,33},bg={255,253,236},cover={{148,637,661,654},{148,656,620,674},{148,677,620,694},{148,695,417,713}},ko="추종자가 처치하거나 작업한 것은 경험치를 주지 않으므로(편법 방지), 직접 마지막 일격을 가해야 진행됩니다. 단 어인 워든, \"버니\", \"맥스웰 그림자 하수인\", 복슬이, \"아비게일\"은 예외입니다."},
		{x=102,y=734,w=604,avail=51,size=26,fg={90,60,33},bg={227,221,204},cover={{137,734,706,758},{102,754,706,781}},ko="스탯 상세 항목의 스탯은 총합 수치입니다. 방어구, 버프, 서 있는 지형까지 포함합니다."},
		{x=774,y=60,w=572,avail=163,size=18,fg={90,60,33},bg={255,253,237},cover={{830,60,1317,76},{774,80,1335,99},{830,100,1296,117},{775,117,1346,135},{830,139,1304,155},{830,160,1312,176},{830,179,1338,196},{830,200,1050,216}},ko="기본적으로 스탯 포인트 초기화는 포인트를 100% 돌려주지 않습니다. 그러나 \"월석 우상\"으로 캐릭터를 바꾸면 포인트를 모두 돌려받으면서 스탯 포인트도 유지됩니다. 이는 초반 몇 년은 특정 스탯이 더 유용하지만 후반에는 공격력에 집중하는 편이 훨씬 낫기 때문입니다. 이렇게 하면 우디나 맥스웰 같은 자원 수집·작업형 캐릭터로 시작한 뒤, 나중에 위그프리드나 윌로우 같은 전투형 캐릭터로 진행 상황을 잃지 않고 바꿀 수 있습니다."},
	},
